class TestSignalProcessing:
    """FFT and vibration feature extraction."""

    def test_fft_features_shape(self, sample_sensor_frame):
        features = compute_fft_features(sample_sensor_frame.vibration_x)
        assert features.shape[0] > 0
        assert np.all(np.isfinite(features))

    def test_fft_dominant_frequency(self):
        # Create 50Hz sine wave
        fs = 10000
        t = np.arange(1024) / fs
        signal = np.sin(2 * np.pi * 50 * t)
        freqs, magnitudes = compute_fft_features(signal, return_full=True)
        dominant_idx = np.argmax(magnitudes)
        assert abs(freqs[dominant_idx] - 50) < 1.0

    def test_vibration_features_extraction(self, sample_sensor_frame):
        features = extract_vibration_features(sample_sensor_frame)
        assert isinstance(features, dict)
        assert "rms_x" in features
        assert "rms_y" in features
        assert "rms_z" in features
        assert "peak_x" in features
        assert "crest_factor_x" in features
        assert all(np.isfinite(v) for v in features.values())

    def test_vibration_features_zero_signal(self):
        frame = SensorFrame(
            timestamp=1.0,
            vibration_x=np.zeros(1024),
            vibration_y=np.zeros(1024),
            vibration_z=np.zeros(1024),
            thermal_array=np.zeros((32, 32)),
            rpm=0.0,
            current_rms=0.0,
        )
        features = extract_vibration_features(frame)
        assert features["rms_x"] == 0.0
        assert features["peak_x"] == 0.0

