class TestTTFModel:
    """Neural network model for TTF forecasting."""

    def test_model_initialization(self, ttf_model):
        assert isinstance(ttf_model, nn.Module)
        assert ttf_model.input_dim == 128
        assert ttf_model.hidden_dim == 256
        assert ttf_model.output_dim == 1

    def test_forward_pass(self, ttf_model):
        batch_size = 4
        x = torch.randn(batch_size, ttf_model.input_dim)
        output = ttf_model(x)
        assert output.shape == (batch_size, ttf_model.output_dim)
        assert torch.all(torch.isfinite(output))

    def test_forward_pass_single_sample(self, ttf_model):
        x = torch.randn(1, ttf_model.input_dim)
        output = ttf_model(x)
        assert output.shape == (1, ttf_model.output_dim)

    def test_model_parameters_updated(self, ttf_model):
        initial_params = [p.clone() for p in ttf_model.parameters()]
        optimizer = torch.optim.Adam(ttf_model.parameters(), lr=0.01)
        x = torch.randn(8, ttf_model.input_dim)
        y = torch.randn(8, ttf_model.output_dim)
        loss_fn = nn.MSELoss()
        optimizer.zero_grad()
        loss = loss_fn(ttf_model(x), y)
        loss.backward()
        optimizer.step()
        for initial, current in zip(initial_params, ttf_model.parameters()):
            assert not torch.equal(initial, current)

    def test_model_gradient_flow(self, ttf_model):
        x = torch.randn(2, ttf_model.input_dim)
        output = ttf_model(x)
        output.sum().backward()
        for param in ttf_model.parameters():
            assert param.grad is not None
            assert torch.all(torch.isfinite(param.grad))

    def test_model_deterministic(self, ttf_model):
        ttf_model.eval()
        x = torch.randn(1, ttf_model.input_dim)
        with torch.no_grad():
            output1 = ttf_model(x)
            output2 = ttf_model(x)
        assert torch.equal(output1, output2)

