class TestSafetyController:
    """Safety state machine and emergency stop logic."""

    def test_initial_state(self, safety_controller):
        assert safety_controller.current_level == SafetyLevel.NORMAL
        assert safety_controller.emergency_stop_threshold == 0.95

    def test_normal_to_yellow(self, safety_controller):
        safety_controller.update_state(risk_score=0.3)
        assert safety_controller.current_level == SafetyLevel.YELLOW

    def test_normal_to_orange(self, safety_controller):
        safety_controller.update_state(risk_score=0.6)
        assert safety_controller.current_level == SafetyLevel.ORANGE

    def test_normal_to_red(self, safety_controller):
        safety_controller.update_state(risk_score=0.8)
        assert safety_controller.current_level == SafetyLevel.RED

    def test_emergency_stop(self, safety_controller):
        safety_controller.update_state(risk_score=0.98)
        assert safety_controller.current_level == SafetyLevel.EMERGENCY_STOP
        assert safety_controller.emergency_stop_triggered is True

    def test_risk_score_boundaries(self, safety_controller):
        # Test boundary conditions
        safety_controller.update_state(risk_score=0.0)
        assert safety_controller.current_level == SafetyLevel.NORMAL
        safety_controller.update_state(risk_score=0.25)
        assert safety_controller.current_level == SafetyLevel.YELLOW
        safety_controller.update_state(risk_score=0.5)
        assert safety_controller.current_level == SafetyLevel.ORANGE
        safety_controller.update_state(risk_score=0.75)
        assert safety_controller.current_level == SafetyLevel.RED
        safety_controller.update_state(risk_score=1.0)
        assert safety_controller.current_level == SafetyLevel.EMERGENCY_STOP

    def test_invalid_risk_score(self, safety_controller):
        with pytest.raises(ValueError, match="risk_score"):
            safety_controller.update_state(risk_score=-0.1)
        with pytest.raises(ValueError, match="risk_score"):
            safety_controller.update_state(risk_score=1.1)

    def test_state_transition_logging(self, safety_controller, caplog):
        with caplog.at_level(logging.INFO):
            safety_controller.update_state(risk_score=0.9)
            assert "RED" in caplog.text
            assert "risk_score" in caplog.text

    def test_emergency_stop_reset(self, safety_controller):
        safety_controller.update_state(risk_score=0.98)
        assert safety_controller.emergency_stop_triggered is True
        safety_controller.reset_emergency_stop()
        assert safety_controller.emergency_stop_triggered is False
        assert safety_controller.current_level == SafetyLevel.NORMAL

    def test_risk_score_combination(self, safety_controller):
        # Test combined risk from multiple sources
        risk = safety_controller.compute_combined_risk(
            ttf_risk=0.4,
            gesture_risk=0.3,
            sensor_risk=0.2,
        )
        assert 0.0 <= risk <= 1.0
        assert risk > 0.4  # Should be amplified

