class TestPerformance:
    """Performance validation under load."""

    @pytest.mark.benchmark
    def test_processing_latency(self, fusion_engine, sample_sensor_frame, benchmark):
        def run_processing():
            return asyncio.run(fusion_engine.process_frame(sample_sensor_frame))
        result = benchmark(run_processing)
        assert result is not None

    def test_throughput(self, fusion_engine, sample_sensor_frame):
        import time
        start = time.time()
        for _ in range(100):
            asyncio.run(fusion_engine.process_frame(sample_sensor_frame))
        elapsed = time.time() - start
        fps = 100 / elapsed
        assert fps > 10  # At least 10 FPS processing rate

    def test_memory_usage(self, fusion_engine, sample_sensor_frame):
        import tracemalloc
        tracemalloc.start()
        for _ in range(50):
            asyncio.run(fusion_engine.process_frame(sample_sensor_frame))
        current, peak = tracemalloc.get_traced_memory()
        tracemalloc.stop()
        assert peak < 500 * 1024 * 1024  # Under 500MB peak

