class TestPropertyBased:
    """Property-based testing for invariants."""

    @pytest.mark.parametrize("seed", range(5))
    def test_risk_score_bounds_property(self, seed):
        rng = np.random.default_rng(seed)
        controller = SafetyController(emergency_stop_threshold=0.95)
        for _ in range(100):
            risk = rng.uniform(0, 1)
            controller.update_state(risk_score=risk)
            assert 0 <= controller.current_level.value <= 4

    @pytest.mark.parametrize("batch_size", [1, 2, 8, 32])
    def test_model_output_shape_property(self, batch_size):
        model = TTFModel(input_dim=128, hidden_dim=256, output_dim=1)
        x = torch.randn(batch_size, 128)
        output = model(x)
        assert output.shape == (batch_size, 1)
        assert torch.all(torch.isfinite(output))

    def test_fft_inverse_property(self):
        # FFT should preserve signal energy (Parseval's theorem)
        rng = np.random.default_rng(0)
        signal = rng.normal(0, 1, 1024)
        time_energy = np.sum(signal ** 2)
        freq_magnitudes = np.abs(rfft(signal))
        freq_energy = np.sum(freq_magnitudes ** 2) / len(signal)
        assert abs(time_energy - freq_energy) < 1e-6

